import { createHash } from 'node:crypto';

// Group constants
export const P = BigInt('0xc135f37294f32354bf0f6657726b3a61a5c4b31f0de34bf8465832f1d7a95637');
export const Q = BigInt('0x609af9b94a7991aa5f87b32bb9359d30d2e2598f86f1a5fc232c1978ebd4ab1b');
export const G = BigInt(4);

/**
 * Compute SHA-256 hash of input and return as hex string
 * @param {string} input - Input string
 * @returns {string} - Hex digest of SHA-256
 */
function sha256hex(input) {
  return createHash('sha256').update(input).digest('hex');
}

/**
 * Challenge function: SHA-256(t1 || "|" || t2) mod Q
 * @param {BigInt} t1 - First group element
 * @param {BigInt} t2 - Second group element
 * @returns {BigInt} - Challenge value mod Q
 */
export function challenge(t1, t2) {
  const hex = sha256hex(t1.toString(16) + '|' + t2.toString(16));
  return BigInt('0x' + hex) % Q;
}

/**
 * Modular exponentiation: base^exp mod p
 * @param {BigInt} base - Base
 * @param {BigInt} exp - Exponent
 * @param {BigInt} mod - Modulus
 * @returns {BigInt} - Result
 */
function modpow(base, exp, mod) {
  return base ** exp % mod;
}

/**
 * Modular inverse using Fermat's little theorem (p is prime)
 * @param {BigInt} a - Value to invert
 * @param {BigInt} p - Prime modulus
 * @returns {BigInt} - Modular inverse
 */
function modinv(a, p) {
  return modpow(a, p - BigInt(2), p);
}

/**
 * Generate a random BigInt in range [0, max)
 * @param {BigInt} max - Exclusive upper bound
 * @returns {BigInt} - Random value
 */
function randomBigInt(max) {
  const byteLength = Math.ceil(max.toString(2).length / 8);
  let r;
  do {
    const bytes = crypto.getRandomValues(new Uint8Array(byteLength));
    r = 0n;
    for (const byte of bytes) {
      r = (r << 8n) | BigInt(byte);
    }
  } while (r >= max);
  return r;
}

// Use Web Crypto if available (Node.js 15+), fallback to node:crypto
const crypto = globalThis.crypto || require('node:crypto').webcrypto;

/**
 * Prove knowledge of discrete log x where y = g^x (mod p)
 * OR proof: prover knows x such that either y1 = g^x or y2 = g^x
 * @param {BigInt} x - Discrete logarithm (secret)
 * @param {which} which - 1 if x is log of y1, 2 if x is log of y2
 * @param {BigInt} y1 - First public value
 * @param {BigInt} y2 - Second public value
 * @returns {Object} - Proof {t1, t2, c1, c2, s1, s2}
 */
export function proveOr(x, which, y1, y2) {
  // For the known branch, we don't use a random commitment yet;
  // we'll compute it after we know the full challenge.
  // For the unknown branch, we choose random c and s values and compute t.

  const unknown = which === 1 ? 2 : 1;

  // Unknown branch: pick random c_unknown and s_unknown
  const c_unknown = randomBigInt(Q);
  const s_unknown = randomBigInt(Q);

  const y_unknown = unknown === 1 ? y1 : y2;
  // t_unknown = g^s_unknown * y_unknown^c_unknown (mod p)
  const t_unknown = (modpow(G, s_unknown, P) * modpow(y_unknown, c_unknown, P)) % P;

  // Known branch: pick random r (temporary commitment)
  const r = randomBigInt(Q);
  // t_known = g^r (mod p)
  const t_known = modpow(G, r, P);

  // Prepare t1, t2 based on which branch is which
  let t1, t2;
  if (which === 1) {
    t1 = t_known;
    t2 = t_unknown;
  } else {
    t1 = t_unknown;
    t2 = t_known;
  }

  // Compute challenge
  const c = challenge(t1, t2);

  // Compute c_known = c - c_unknown (mod Q)
  let c_known = (c - c_unknown) % Q;
  if (c_known < 0n) c_known += Q;

  // Compute s_known = r + c_known * x (mod Q)
  const s_known = (r + c_known * x) % Q;

  // Return proof with c1, c2, s1, s2 in order
  let c1, c2, s1, s2;
  if (which === 1) {
    c1 = c_known;
    c2 = c_unknown;
    s1 = s_known;
    s2 = s_unknown;
  } else {
    c1 = c_unknown;
    c2 = c_known;
    s1 = s_unknown;
    s2 = s_known;
  }

  return { t1, t2, c1, c2, s1, s2 };
}

/**
 * Verify an OR-proof
 * @param {BigInt} y1 - First public value
 * @param {BigInt} y2 - Second public value
 * @param {Object} proof - Proof object {t1, t2, c1, c2, s1, s2}
 * @returns {boolean} - Whether proof is valid
 */
export function verifyOr(y1, y2, proof) {
  const { t1, t2, c1, c2, s1, s2 } = proof;

  // Check: c1 + c2 = challenge(t1, t2) (mod Q)
  const expectedChallenge = challenge(t1, t2);
  const sumC = (c1 + c2) % Q;
  if (sumC !== expectedChallenge) {
    return false;
  }

  // Check: g^s1 = t1 * y1^c1 (mod p)
  const lhs1 = modpow(G, s1, P);
  const rhs1 = (t1 * modpow(y1, c1, P)) % P;
  if (lhs1 !== rhs1) {
    return false;
  }

  // Check: g^s2 = t2 * y2^c2 (mod p)
  const lhs2 = modpow(G, s2, P);
  const rhs2 = (t2 * modpow(y2, c2, P)) % P;
  if (lhs2 !== rhs2) {
    return false;
  }

  return true;
}
